scenes, caps = [], []
for i, ch, j, t, sp, cap, on, scr, act, res, seg in S:
    scenes.append(
        {
            "id": i,
            "chapter": ch,
            "journey": j,
            "title": t,
            "voiceover": sp,
            "caption": cap or sp,
            "onscreen": on,
            "screen": scr,
            "actions": act,
            "result": res,
            "segment": seg,
            "targetSeconds": round(len(sp.split()) / 2.3 + 3, 1),
        }
    )
    caps.append({"id": i, "voiceover": cap or sp})

with open("scenes.json", "w", encoding="utf-8") as f:
    json.dump({"version": "1.0.0", "fps": 30, "size": "1920x1080", "scenes": scenes}, f, indent=2, ensure_ascii=False)
with open("scenes-captions.json", "w", encoding="utf-8") as f:
    json.dump({"scenes": caps}, f, indent=2, ensure_ascii=False)
tot = sum(len(s["voiceover"].split()) for s in scenes)
print("scenes", len(scenes), "words", tot, "est speech sec", round(tot / 2.3))
